css_code:
/* 固定ページヘッダー：タイトル背景色 */
#page_header .square_headline {
  background-color: #4F765EDD;
}


/* TOPページ：スマホ表示調整 */
@media screen and (max-width: 767px) {

  /* 見出しサイズ */
  .ss-top-main h2,
  .ss-top-matsumura h2 {
    font-size: 24px !important;
    line-height: 1.45 !important;
    letter-spacing: 0 !important;
  }

  .ss-top-main h3,
  .ss-top-matsumura h3 {
    font-size: 18px !important;
    line-height: 1.55 !important;
    letter-spacing: 0 !important;
  }


  /* PC用の強制改行をスマホでは無効化 */
  .ss-top-main h2 br,
  .ss-top-matsumura h2 br {
    display: none !important;
  }


  /* TOP本文の横ズレ防止 */
  .ss-top-main {
    box-sizing: border-box !important;
    width: 100% !important;
    max-width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
    padding-left: 8px !important;
    padding-right: 8px !important;
  }

  .ss-top-matsumura {
    box-sizing: border-box !important;
    max-width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
    padding-left: 8px !important;
    padding-right: 8px !important;
  }


  /* 日本語見出しの折り返しを自然にする */
  .ss-top-main h2,
  .ss-top-main h3,
  .ss-top-matsumura h2,
  .ss-top-matsumura h3 {
    text-wrap: balance;
    word-break: auto-phrase;
  }


  /* スマホ時のコンテンツ内側余白を縮小 */
  .ss-top-main > div[style*="padding:34px 28px"],
  .ss-top-main > div[style*="padding:34px 24px"],
  .ss-top-main > div[style*="padding:48px 32px"],
  .ss-top-main > div[style*="padding:46px 32px"],
  .ss-top-main > div[style*="padding:30px 22px"] {
    padding-left: 16px !important;
    padding-right: 16px !important;
  }


  /* 松村さんパート内のカード余白 */
  .ss-top-matsumura div[style*="padding:18px 20px"] {
    padding-left: 14px !important;
    padding-right: 14px !important;
  }

}
